Complex div(Complex a, Complex b) {
	long double mo = b.norm();
	Complex c = a * b.conj();
	long double r = 1. * c.r / mo, i = 1. * c.i / mo;
	return Complex(round(r), round(i));
}
Complex gcd(Complex a, Complex b) {
	if (b.r == 0 && b.i == 0) return a;
	Complex c = div(a, b);
	return gcd(b, a - b * c);
}

