inline void rotate (int x) {
    int y = fa[x], z = fa[y], k = get(x);
    ch[y][k] = ch[x][!k]; fa[ch[x][!k]] = y;
    fa[x] = z; if(z) ch[z][ch[z][1] == y] = x; 
	ch[x][!k] = y, fa[y] = x;
}

inline void splay (int x){
    int p;
    for (p = fa[x]; p = fa[x], p; rotate(x))
        if (fa[p])  get(x) == get(p) ? rotate(p) : rotate(x);
