			int lca = LCA(u, v);
			int tmp = LCA(u, rt);
			(dep[tmp] > dep[lca]) ? lca = tmp : Mck = 1;  
			tmp = LCA(v, rt);
			(dep[tmp] > dep[lca]) ? lca = tmp : Mck = 1;
			int llccaa = LCA(lca, rt);
			if (llccaa != lca && llccaa != rt) {
				update(1, 1, n, dfn[lca], low[lca], det); 
				continue;
			}
			if (lca == rt) push(1, 1, n, det);
			else if (llccaa == rt) {
				update (1, 1, n, dfn[lca], low[lca], det); 
			}
			else {
				Mck = LCA_son(lca, rt);
				push(1, 1, n, det);
				update(1, 1, n, dfn[Mck], low[Mck], -det); 
			}
		}
